  "landing.hero.badge": "100% \u0c89\u0c9a\u0cbf\u0ca4 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0c96\u0cbe\u0cb8\u0c97\u0cbf",
  "landing.hero.h1": "\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbe\u0cb0\u0c95\u0ccd\u0c95\u0cc6 \u0cb8\u0cb0\u0cbf\u0caf\u0cbe\u0ca6 \u0cb8\u0cb0\u0ccd\u0c95\u0cbe\u0cb0\u0cbf \u0caf\u0ccb\u0c9c\u0ca8\u0cc6\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0c95\u0c82\u0ca1\u0cc1\u0c95\u0cca\u0cb3\u0ccd\u0cb3\u0cbf",
  "landing.hero.h1.accent": "\u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbe\u0cb0",
  "landing.hero.sub": "VittVanni \u0cad\u0cbe\u0cb0\u0ca4\u0ca6 \u0c95\u0cc7\u0c82\u0ca6\u0ccd\u0cb0 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0cb0\u0cbe\u0c9c\u0ccd\u0caf \u0cb8\u0cb0\u0ccd\u0c95\u0cbe\u0cb0\u0ca6 \u0caf\u0ccb\u0c9c\u0ca8\u0cc6\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0caa\u0ccd\u0cb0\u0cca\u0cab\u0cc8\u0cb2\u0ccd\u0c97\u0cc6 \u0cb9\u0cca\u0c82\u0ca6\u0cbf\u0cb8\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6 \u2014 \u0cb8\u0cb0\u0cb3 \u0c95\u0ca8\u0ccd\u0ca8\u0ca1, \u0cb9\u0c82\u0ca4 \u0cb9\u0c82\u0ca4\u0cb5\u0cbe\u0c97\u0cbf.",
  "landing.hero.cta": "\u0cb9\u0cca\u0c82\u0ca6\u0cbe\u0ca3\u0cbf\u0c95\u0cc6 \u0caa\u0ccd\u0cb0\u0cbe\u0cb0\u0c82\u0cad\u0cbf\u0cb8\u0cbf",
  "landing.hero.cta2": "\u0c87\u0ca6\u0cc1 \u0cb9\u0cc7\u0c97\u0cc6 \u0c95\u0cc6\u0cb2\u0cb8 \u0cae\u0cbe\u0ca1\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6",
  "landing.how.title": "\u0c87\u0ca6\u0cc1 \u0cb9\u0cc7\u0c97\u0cc6 \u0c95\u0cc6\u0cb2\u0cb8 \u0cae\u0cbe\u0ca1\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6",
  "landing.how.1.title": "\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cac\u0c97\u0ccd\u0c97\u0cc6 \u0cb9\u0cc7\u0cb3\u0cbf",
  "landing.how.1.text": "\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbe\u0cb0, \u0cb8\u0ccd\u0ca5\u0cb3 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0cb9\u0cbf\u0ca8\u0ccd\u0ca8\u0cc6\u0cb2\u0cc6 \u0cac\u0c97\u0ccd\u0c97\u0cc6 9 \u0cb8\u0cc1\u0cb2\u0cad \u0caa\u0ccd\u0cb0\u0cb6\u0ccd\u0ca8\u0cc6\u0c97\u0cb3\u0cbf\u0c97\u0cc6 \u0c89\u0ca4\u0ccd\u0ca4\u0cb0\u0cbf\u0cb8\u0cbf.",
  "landing.how.2.title": "\u0ca8\u0cbe\u0cb5\u0cc1 \u0ca8\u0cbf\u0cae\u0ccd\u0cae\u0ca8\u0ccd\u0ca8\u0cc1 \u0cb9\u0cca\u0c82\u0ca6\u0cbf\u0cb8\u0cc1\u0ca4\u0ccd\u0ca4\u0cc7\u0cb5\u0cc6",
  "landing.how.2.text": "\u0ca8\u0cae\u0ccd\u0cae \u0cb5\u0ccd\u0caf\u0cb5\u0cb8\u0ccd\u0ca5\u0cc6 \u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0c89\u0ca4\u0ccd\u0ca4\u0cb0\u0c97\u0cb3\u0cbf\u0c82\u0ca6 14 \u0cb5\u0cb2\u0caf\u0c97\u0cb3\u0cb2\u0ccd\u0cb2\u0cbf 90+ \u0caf\u0ccb\u0c9c\u0ca8\u0cc6\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0cb6\u0ccd\u0cb0\u0cc7\u0caf\u0cbe\u0c82\u0c95\u0cbf\u0cb8\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6.",
  "landing.how.3.title": "\u0cb5\u0cbf\u0cb5\u0cb0\u0ca3\u0cc6 \u0caa\u0ca1\u0cc6\u0caf\u0cbf\u0cb0\u0cbf",
  "landing.how.3.text": "\u0caa\u0ccd\u0cb0\u0ca4\u0cbf \u0caf\u0ccb\u0c9c\u0ca8\u0cc6 \u0c8f\u0c95\u0cc6 \u0cb9\u0cca\u0c82\u0ca6\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6 \u0c8e\u0c82\u0cac \u0cb8\u0ccd\u0caa\u0cb7\u0ccd\u0c9f \u0c95\u0cbe\u0cb0\u0ca3 \u2014 \u0c95\u0ca0\u0cbf\u0ca3 \u0caa\u0ca6\u0c97\u0cb3\u0cbf\u0cb2\u0ccd\u0cb2\u0ca6\u0cc6.",
  "landing.how.4.title": "\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cbe\u0cb8\u0ca6\u0cbf\u0c82\u0ca6 \u0c85\u0cb0\u0ccd\u0c9c\u0cbf \u0cb8\u0cb2\u0ccd\u0cb2\u0cbf\u0cb8\u0cbf",
  "landing.how.4.text": "\u0ca6\u0cbe\u0c96\u0cb2\u0cc6\u0c97\u0cb3\u0cc1, \u0ca6\u0cbf\u0ca8\u0cbe\u0c82\u0c95\u0c97\u0cb3\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0cb5\u0cbe\u0cb0\u0cb5\u0cbe\u0cb0\u0cc1 \u0c85\u0cb0\u0ccd\u0c9c\u0cbf \u0cb0\u0ccb\u0ca1\u0ccd\u0cae\u0ccd\u0caf\u0cbe\u0caa\u0ccd \u0caa\u0ca1\u0cc6\u0caf\u0cbf\u0cb0\u0cbf.",
  "landing.stats.title": "\u0cac\u0cc6\u0cb3\u0cc6\u0caf\u0cc1\u0ca4\u0ccd\u0ca4\u0cbf\u0cb0\u0cc1\u0cb5 \u0c89\u0ca6\u0ccd\u0caf\u0cae\u0cbf\u0c97\u0cb3 \u0ca8\u0c82\u0cac\u0cbf\u0c95\u0cc6",
  "landing.stats.schemes": "\u0cb8\u0cc7\u0cb0\u0cbf\u0cb8\u0cb2\u0cbe\u0ca6 \u0caf\u0ccb\u0c9c\u0ca8\u0cc6\u0c97\u0cb3\u0cc1",
  "landing.stats.sectors": "\u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbe\u0cb0 \u0cb5\u0cb2\u0caf\u0c97\u0cb3\u0cc1",
  "landing.stats.states": "\u0cb8\u0cc7\u0cb0\u0cbf\u0cb8\u0cb2\u0cbe\u0ca6 \u0cb0\u0cbe\u0c9c\u0ccd\u0caf\u0c97\u0cb3\u0cc1",
  "landing.stats.languages": "\u0cad\u0cbe\u0cb7\u0cc6\u0c97\u0cb3\u0cc1",
  "landing.features.title": "\u0ca8\u0cbf\u0c9c\u0cb5\u0cbe\u0ca6 \u0c89\u0ca6\u0ccd\u0caf\u0cae\u0cbf\u0c97\u0cb3\u0cbf\u0c97\u0cbe\u0c97\u0cbf \u0ca4\u0caf\u0cbe\u0cb0\u0cbf\u0cb8\u0cb2\u0cbe\u0c97\u0cbf\u0ca6\u0cc6",
  "landing.features.1.title": "\u0cae\u0cca\u0ca6\u0cb2\u0cc1 \u0ca7\u0ccd\u0cb5\u0ca8\u0cbf + \u0caa\u0ca0\u0ccd\u0caf",
  "landing.features.1.text": "\u0caf\u0cbe\u0cb5\u0cc1\u0ca6\u0cc7 \u0cab\u0ccb\u0ca8\u0ccd\u0ca8\u0cb2\u0ccd\u0cb2\u0cbf, \u0c95\u0ca1\u0cbf\u0cae\u0cc6 \u0ca1\u0cc7\u0c9f\u0cbe\u0ca6\u0cb2\u0ccd\u0cb2\u0cc2 \u0cb2\u0c98\u0cc1\u0cb5\u0cbe\u0c97\u0cbf \u0c95\u0cc6\u0cb2\u0cb8 \u0cae\u0cbe\u0ca1\u0cc1\u0cb5 \u0cb5\u0cbf\u0ca8\u0ccd\u0caf\u0cbe\u0cb8.",
  "landing.features.2.title": "23 \u0cad\u0cbe\u0cb7\u0cc6\u0c97\u0cb3\u0cc1",
  "landing.features.2.text": "\u0cae\u0cc7\u0cb2\u0cbf\u0ca8 \u0cae\u0cc6\u0ca8\u0cc1\u0cb5\u0cbf\u0ca8\u0cbf\u0c82\u0ca6 \u0caf\u0cbe\u0cb5\u0cc1\u0ca6\u0cc7 \u0cad\u0cbe\u0cb0\u0ca4\u0cc0\u0caf \u0cad\u0cbe\u0cb7\u0cc6 \u0c86\u0caf\u0ccd\u0c95\u0cc6\u0cae\u0cbe\u0ca1\u0cbf.",
  "landing.features.3.title": "\u0c86\u0cab\u0ccd\u0cb2\u0cc8\u0ca8\u0ccd-\u0cb8\u0ccd\u0ca8\u0cc7\u0cb9\u0cbf",
  "landing.features.3.text": "\u0caf\u0ccb\u0c9c\u0ca8\u0cc6\u0c97\u0cb3\u0cc1 \u0cb2\u0ccb\u0c95\u0cb2\u0ccd \u0c95\u0ccd\u0caf\u0cbe\u0cb6\u0ccd\u0ca8\u0cb2\u0ccd\u0cb2\u0cbf\u0cb0\u0cc1\u0ca4\u0ccd\u0ca4\u0cb5\u0cc6 \u2014 \u0c87\u0c82\u0c9f\u0cb0\u0ccd\u0ca8\u0cc6\u0c9f\u0ccd \u0c87\u0cb2\u0ccd\u0cb2\u0ca6\u0cc6\u0caf\u0cc2 \u0ca8\u0ccb\u0ca1\u0cac\u0cb9\u0cc1\u0ca6\u0cc1.",
  "landing.features.4.title": "\u0c97\u0ccb\u0caa\u0ccd\u0caf\u0ca4\u0cc6\u0c97\u0cc6 \u0c86\u0ca6\u0ccd\u0caf\u0ca4\u0cc6",
  "landing.features.4.text": "\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0ca1\u0cc7\u0c9f\u0cbe \u0ca8\u0cbf\u0cae\u0ccd\u0cae\u0ca6\u0cc7 \u0c86\u0c97\u0cbf\u0cb0\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6. \u0c8e\u0c82\u0ca6\u0cbf\u0c97\u0cc2 \u0cae\u0cbe\u0cb0\u0cb2\u0cbe\u0c97\u0cc1\u0cb5\u0cc1\u0ca6\u0cbf\u0cb2\u0ccd\u0cb2.",
  "landing.cta.title": "\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0caf\u0ccb\u0c9c\u0ca8\u0cc6 \u0c95\u0c82\u0ca1\u0cc1\u0cb9\u0cbf\u0ca1\u0cbf\u0caf\u0cb2\u0cc1 \u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cb0\u0cc7?",
  "landing.cta.text": "\u0c87\u0ca6\u0c95\u0ccd\u0c95\u0cc6 5 \u0ca8\u0cbf\u0cae\u0cbf\u0cb7\u0c97\u0cb3\u0cbf\u0c97\u0cbf\u0c82\u0ca4 \u0c95\u0ca1\u0cbf\u0cae\u0cc6 \u0cb8\u0cae\u0caf \u0cac\u0cc7\u0c95\u0cbe\u0c97\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6.",
  "auth.login.title": "\u0cb8\u0ccd\u0cb5\u0cbe\u0c97\u0ca4",
  "auth.login.sub": "\u0cb9\u0cca\u0c82\u0ca6\u0cbe\u0ca3\u0cbf\u0c95\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0cbe\u0ca3 \u0cae\u0cc1\u0c82\u0ca6\u0cc1\u0cb5\u0cb0\u0cbf\u0cb8\u0cb2\u0cc1 \u0cb2\u0cbe\u0c97\u0cbf\u0ca8\u0ccd \u0cae\u0cbe\u0ca1\u0cbf",
