  "questionnaire.gate.noProfileNote": "\u0caa\u0ccd\u0cb0\u0ca4\u0ccd\u0caf\u0cc7\u0c95 \u0caa\u0ccd\u0cb0\u0cca\u0cab\u0cc8\u0cb2\u0ccd \u0cab\u0cbe\u0cb0\u0ccd\u0cae\u0ccd \u0c85\u0c97\u0ca4\u0ccd\u0caf\u0cb5\u0cbf\u0cb2\u0ccd\u0cb2 \u2014 \u0cb5\u0cbf\u0cb5\u0cb0\u0cbf\u0cb8\u0cbf, \u0ca8\u0cbe\u0cb5\u0cc1 \u0cb0\u0c9a\u0cbf\u0cb8\u0cc1\u0ca4\u0ccd\u0ca4\u0cc7\u0cb5\u0cc6.",
  "questionnaire.describe.title": "\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cb6\u0cac\u0ccd\u0ca6\u0c97\u0cb3\u0cb2\u0ccd\u0cb2\u0cbf \u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbe\u0cb0\u0ca6 \u0cac\u0c97\u0ccd\u0c97\u0cc6 \u0cb9\u0cc7\u0cb3\u0cbf",
  "questionnaire.describe.help": "\u0ca8\u0cc0\u0cb5\u0cc1 \u0c8f\u0ca8\u0cc1 \u0cae\u0cbe\u0ca1\u0cc1\u0ca4\u0ccd\u0ca4\u0cc0\u0cb0\u0cbf, \u0c85\u0ca6\u0cc1 \u0ca8\u0ca1\u0cc6\u0caf\u0cc1\u0ca4\u0ccd\u0ca4\u0cbf\u0ca6\u0cc6\u0caf\u0cc7 \u0c85\u0ca5\u0cb5\u0cbe \u0caa\u0ccd\u0cb0\u0cbe\u0cb0\u0c82\u0cad\u0cb5\u0cbe\u0c97\u0cc1\u0ca4\u0ccd\u0ca4\u0cbf\u0ca6\u0cc6\u0caf\u0cc7, \u0caf\u0cbe\u0cb5 \u0cb8\u0cb9\u0cbe\u0caf \u0cac\u0cc7\u0c95\u0cc6\u0c82\u0ca6\u0cc1 (\u0cb8\u0cbe\u0cb2, \u0ca4\u0cb0\u0cac\u0cc7\u0ca4\u0cbf, \u0cae\u0cbe\u0cb0\u0cbe\u0c9f \u0cb8\u0cb9\u0cbe\u0caf \u0c87\u0ca4\u0ccd\u0caf\u0cbe\u0ca6\u0cbf) \u2014 \u0cb9\u0cc7\u0cb3\u0cbf. \u0cae\u0cbe\u0ca4\u0ca8\u0cbe\u0ca1\u0cbf\u0caf\u0cc2 \u0cb9\u0cc7\u0cb3\u0cac\u0cb9\u0cc1\u0ca6\u0cc1.",
